// TwoFactorEnterEmailCodeTo is the package's TwoFactorEnterEmailCodeTo in the language of msgs.
func (msgs Messages) TwoFactorEnterEmailCodeTo(email string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.TwoFactorEnterEmailCodeTo(email))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].TwoFactorEnterEmailCodeTo; f != nil {
			return f(email)
		}
		switch lang {
		case "", "en":
			return "Enter the code sent to " + msgs.arg(email) + "."
		case "de":
			return "Gib den Code ein, der an " + email + " gesendet wurde."
		case "es":
			return "Introduce el código enviado a " + email + "."
		case "fr":
			return "Saisissez le code envoyé à " + email + "."
		case "ja":
			return email + " に送信された認証コードを入力してください。"
		case "ko":
			return email + "(으)로 전송된 인증 코드를 입력하세요."
		case "pt-BR":
			return "Digite o código enviado para " + email + "."
		case "ru":
			return "Введите код, отправленный на " + email + "."
		case "zh-Hans":
			return "请输入发送至 " + email + " 的验证码。"
		case "zh-Hant":
			return "請輸入傳送至 " + email + " 的驗證碼。"
		}
	}
}

