// NothingInSectionMatches says "Nothing in {section} matches “{query}”."
// in the language the app shows under cx.
//
// section is a sidebar section, such as Logins or a folder's name; query is what the user typed.
func NothingInSectionMatches(cx *core.Scope, section string, query string) string {
	return For(cx).NothingInSectionMatches(section, query)
}

// NothingInSectionMatches is the package's NothingInSectionMatches in the language of msgs.
func (msgs Messages) NothingInSectionMatches(section string, query string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.NothingInSectionMatches(section, query))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].NothingInSectionMatches; f != nil {
			return f(section, query)
		}
		switch lang {
		case "", "en":
			return "Nothing in " + msgs.arg(section) + " matches “" + msgs.arg(query) + "”."
		case "de":
			return "Keine Treffer für „" + query + "“ in „" + section + "“."
		case "es":
			return "Nada en “" + section + "” coincide con “" + query + "”."
		case "fr":
			return "Aucun résultat pour « " + query + " » dans « " + section + " »."
		case "ja":
			return "「" + section + "」に「" + query + "」と一致するアイテムはありません。"
		case "ko":
			return "“" + section + "”에서 “" + query + "”와(과) 일치하는 항목이 없습니다."
		case "pt-BR":
			return "Nada em “" + section + "” corresponde a “" + query + "”."
		case "ru":
			return "В «" + section + "» нет совпадений для «" + query + "»."
		case "zh-Hans":
			return "“" + section + "”中没有与“" + query + "”匹配的项目。"
		case "zh-Hant":
			return "「" + section + "」中沒有符合「" + query + "」的項目。"
		}
	}
}

