// ErrorServer says "The server reported an error ({status}): {detail}"
// in the language the app shows under cx.
//
// status is an HTTP status code; detail is the server's own message, untranslated.
func ErrorServer(cx *core.Scope, status string, detail string) string {
	return For(cx).ErrorServer(status, detail)
}

// ErrorServer is the package's ErrorServer in the language of msgs.
func (msgs Messages) ErrorServer(status string, detail string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.ErrorServer(status, detail))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].ErrorServer; f != nil {
			return f(status, detail)
		}
		switch lang {
		case "", "en":
			return "The server reported an error (" + msgs.arg(status) + "): " + msgs.arg(detail)
		case "de":
			return "Der Server meldete einen Fehler (" + status + "): " + detail
		case "es":
			return "El servidor devolvió un error (" + status + "): " + detail
		case "fr":
			return "Le serveur a renvoyé une erreur (" + status + ") : " + detail
		case "ja":
			return "サーバーエラー（" + status + "）：" + detail
		case "ko":
			return "서버 오류 (" + status + "): " + detail
		case "pt-BR":
			return "O servidor retornou um erro (" + status + "): " + detail
		case "ru":
			return "Ошибка сервера (" + status + "): " + detail
		case "zh-Hans":
			return "服务器返回错误（" + status + "）：" + detail
		case "zh-Hant":
			return "伺服器回傳錯誤（" + status + "）：" + detail
		}
	}
}

// ErrorWithDetail says "Something went wrong: {detail}"
// in the language the app shows under cx.
//
// A fallback for an error GoVault has no message for; detail is its technical description, untranslated.
func ErrorWithDetail(cx *core.Scope, detail string) string { return For(cx).ErrorWithDetail(detail) }

// ErrorWithDetail is the package's ErrorWithDetail in the language of msgs.
func (msgs Messages) ErrorWithDetail(detail string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.ErrorWithDetail(detail))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].ErrorWithDetail; f != nil {
			return f(detail)
		}
		switch lang {
		case "", "en":
			return "Something went wrong: " + msgs.arg(detail)
		case "de":
			return "Etwas ist schiefgelaufen: " + detail
		case "es":
			return "Algo salió mal: " + detail
		case "fr":
			return "Une erreur est survenue : " + detail
		case "ja":
			return "エラーが発生しました：" + detail
		case "ko":
			return "오류가 발생했습니다: " + detail
		case "pt-BR":
			return "Algo deu errado: " + detail
		case "ru":
			return "Произошла ошибка: " + detail
		case "zh-Hans":
			return "出现错误：" + detail
		case "zh-Hant":
			return "發生錯誤：" + detail
		}
	}
}

